function loadDb() {
  try { return JSON.parse(fs.readFileSync(DB_PATH, 'utf8')); } catch { const d = seedDb(); saveDb(d); return d; }
}
function saveDb(db) {
  const tmp = DB_PATH + '.tmp';
  fs.writeFileSync(tmp, JSON.stringify(db, null, 2));
  fs.renameSync(tmp, DB_PATH);
}
let db = loadDb();
function loadOutbox() { try { return JSON.parse(fs.readFileSync(OUTBOX_PATH, 'utf8')); } catch { return []; } }
function saveOutbox(list) {
  const tmp = OUTBOX_PATH + '.tmp';
  fs.writeFileSync(tmp, JSON.stringify(list, null, 2));
  fs.renameSync(tmp, OUTBOX_PATH);
}

// Password hashing: scrypt, salted. Stored format: scrypt:<saltHex>:<hashHex>
function hashPassword(pw) {
  const salt = crypto.randomBytes(16).toString('hex');
  const hash = crypto.scryptSync(pw, salt, 64).toString('hex');
  return `scrypt:${salt}:${hash}`;
}
function verifyPassword(pw, stored) {
  try {
    const [, salt, hash] = stored.split(':');
    const check = crypto.scryptSync(pw, salt, 64).toString('hex');
    return crypto.timingSafeEqual(Buffer.from(hash, 'hex'), Buffer.from(check, 'hex'));
  } catch { return false; }
}
function hashToken(t) { return crypto.createHash('sha256').update(t).digest('hex'); }

// LIVE password format: exactly 8 characters, mixing numbers, letters,
// and symbols # @ * $. Guaranteed at least one of each class, shuffled
// with crypto RNG. Used for signup and forgot-password in live-ready mode.
function generateLivePassword() {
  const digits = '0123456789';
  const letters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const symbols = '#@*$';
  const all = digits + letters + symbols;
  const pick = (s) => s[crypto.randomInt(s.length)];
  const chars = [pick(digits), pick(letters), pick(symbols)];
  while (chars.length < 8) chars.push(pick(all));
  for (let i = chars.length - 1; i > 0; i--) { const j = crypto.randomInt(i + 1); [chars[i], chars[j]] = [chars[j], chars[i]]; }
  return chars.join('');
}

async function sendPasswordEmail(to, password) {
  // Real email ONLY if SMTP env vars are set. Otherwise demo mode:
  // save to data/outbox.json and log to console only — never to a page.
  // LIVE_MODE=1 guard: never pretend a live email was sent. If SMTP is
  // not configured, return false so callers do NOT create/replace a
  // password the user can never receive.
  const { SMTP_HOST, SMTP_PORT, SMTP_USER, SMTP_PASS, SMTP_FROM } = process.env;
  if (SMTP_HOST && SMTP_USER && SMTP_PASS) {
    try {
      const nodemailer = require('nodemailer');
      const t = nodemailer.createTransport({ host: SMTP_HOST, port: Number(SMTP_PORT || 587), secure: Number(SMTP_PORT) === 465, auth: { user: SMTP_USER, pass: SMTP_PASS } });
      await t.sendMail({ from: SMTP_FROM || SMTP_USER, to, subject: 'Your Apnar digital password', text: `Your Apnar digital password is: ${password}\nLog in with your email and this password.` });
      console.log(`Email sent to ${to} via SMTP`);
      return true;
    } catch (e) {
      console.log('SMTP send failed:', e.message);
      if (process.env.LIVE_MODE === '1') return false;
      const o = loadOutbox(); o.push({ to, subject: 'Your Apnar digital password', sentAt: new Date().toISOString(), note: 'SMTP failed, saved to outbox' }); saveOutbox(o);
      return true;
    }
  }
  if (process.env.LIVE_MODE === '1') { console.log('LIVE MODE — no SMTP configured, refusing to issue a password'); return false; }
  const o = loadOutbox();
  o.push({ to, subject: 'Your Apnar digital password', password, sentAt: new Date().toISOString(), note: 'DEMO MODE — no real email sent' });
  saveOutbox(o);
  console.log('DEMO MODE — no real email sent, check outbox');
  return true;
}

function parseCookies(req) {
  const out = {};
  (req.headers.cookie || '').split(';').forEach((p) => { const i = p.indexOf('='); if (i > 0) out[p.slice(0, i).trim()] = decodeURIComponent(p.slice(i + 1).trim()); });
  return out;
}
const SESSION_MS = 30 * 24 * 60 * 60 * 1000; // 30 days: stay logged in until explicit logout
function currentUser(req) {
  const token = parseCookies(req).session;
  if (!token) return null;
  const s = db.sessions.find((x) => x.tokenHash === hashToken(token));
  if (!s) return null;
  if (s.expiresAt && Date.now() > s.expiresAt) {
    db.sessions = db.sessions.filter((x) => x.tokenHash !== s.tokenHash); saveDb(db); return null;
  }
  return db.users.find((u) => u.id === s.userId) || null;
}
function setSession(res, user) {
  const token = crypto.randomBytes(32).toString('hex');
  db.sessions.push({ tokenHash: hashToken(token), userId: user.id, createdAt: new Date().toISOString(), expiresAt: Date.now() + SESSION_MS });
  saveDb(db);
  res.setHeader('Set-Cookie', `session=${token}; HttpOnly; Path=/; SameSite=Lax; Max-Age=${Math.floor(SESSION_MS / 1000)}`);
}
function clearSession(req, res) {
  const token = parseCookies(req).session;
  if (token) { db.sessions = db.sessions.filter((x) => x.tokenHash !== hashToken(token)); saveDb(db); }
  res.setHeader('Set-Cookie', 'session=; HttpOnly; Path=/; Max-Age=0');
}
function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on('data', (c) => chunks.push(c));
    req.on('end', () => resolve(Buffer.concat(chunks)));
    req.on('error', reject);
  });
}
function json(res, status, obj) { res.writeHead(status, { 'Content-Type': 'application/json' }); res.end(JSON.stringify(obj)); }
function publicUser(u) { return u ? { id: u.id, email: u.email, role: u.role } : null; }
function findItem(id) { for (const s of db.services) { const it = s.items.find((x) => x.id === id); if (it) return { service: s, item: it }; } return null; }
function sanitiseService(s) {
  // Prompt items: no price/stock fields exposed at all.
  return { slug: s.slug, name: s.name, title: s.title, short: s.short, full: s.full,
    items: s.items.map((it) => s.slug === 'prompt' ? { id: it.id, title: it.title, blurb: it.blurb, image: it.image || '' } : { id: it.id, title: it.title, blurb: it.blurb, price: it.price || '', stock: it.stock || '', image: it.image || '' }) };
}

// Minimal multipart parser (single file field + text fields), binary-safe via Buffer.
function parseMultipart(buf, boundary) {
  const parts = [];
  const sep = Buffer.from('--' + boundary);
  let start = buf.indexOf(sep);
  while (start !== -1) {
    const headerEnd = buf.indexOf('\r\n\r\n', start);
    if (headerEnd === -1) break;
    const headers = buf.slice(start + sep.length + 2, headerEnd).toString();
    const next = buf.indexOf(sep, headerEnd);
    if (next === -1) break;
    const body = buf.slice(headerEnd + 4, next - 2);
    const nameM = /name="([^"]+)"/.exec(headers);
    const fileM = /filename="([^"]*)"/.exec(headers);
    parts.push({ name: nameM ? nameM[1] : '', filename: fileM ? fileM[1] : '', headers, body });
    start = next;
  }
  return parts;
}

const MIME = { '.html': 'text/html', '.css': 'text/css', '.js': 'application/javascript', '.json': 'application/json', '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.gif': 'image/gif', '.webp': 'image/webp', '.svg': 'image/svg+xml' };
function serveFile(res, file, fallbackHtml) {
  const ext = path.extname(file).toLowerCase();
  fs.readFile(file, (err, data) => {
    if (err) { if (fallbackHtml) { res.writeHead(200, { 'Content-Type': 'text/html' }); res.end(fallbackHtml); } else { res.writeHead(404); res.end('Not found'); } return; }
    res.writeHead(200, { 'Content-Type': MIME[ext] || 'application/octet-stream' }); res.end(data);
  });
}

async function handleRequest(req, res) {
  try {
    const url = new URL(req.url, 'http://local');
    // Vercel gateway (temp copy only): Vercel's file-upload deployment builds
    // only api/index.js into a function, so vercel.json rewrites every route
    // to /api/index?path=<original>. Restore the original path here.
    let p = url.pathname;
    if (p === '/api/index' || p === '/api/index.js') {
      const apiGw = url.searchParams.get('api');
      const pathGw = url.searchParams.get('path');
      if (apiGw !== null) {
        const gw = apiGw.replace(/^\/+/, '');
        p = gw ? '/api/' + gw : '/api/services';
      } else if (pathGw !== null) {
        const gw = pathGw.replace(/^\/+/, '');
        p = gw ? '/' + gw : '/';
      }
    }
    // Static uploads
    if (p.startsWith('/uploads/')) {
      const safe = path.normalize(path.join(UPLOAD_DIR, p.slice('/uploads/'.length))).replace(/^(\.\.(\/|\\|$))+/, '');
      if (!safe.startsWith(UPLOAD_DIR)) { res.writeHead(403); return res.end('Forbidden'); }
      return serveFile(res, safe);
    }
    // Static public files
    if (p === '/' || p === '/index.html') return serveFile(res, path.join(PUBLIC_DIR, 'index.html'));
    if (p === '/admin' || p === '/admin.html') return serveFile(res, path.join(PUBLIC_DIR, 'admin.html'));
    if (p === '/admin-setup' || p === '/admin-setup.html') return serveFile(res, path.join(PUBLIC_DIR, 'admin-setup.html'));
    if (p.startsWith('/public/')) return serveFile(res, path.join(PUBLIC_DIR, p.slice('/public/'.length)));

    if (!p.startsWith('/api/')) { const f = path.join(PUBLIC_DIR, '404.html'); return fs.readFile(f, (e, data) => { if (e) { res.writeHead(404); return res.end('Not found'); } res.writeHead(404, { 'Content-Type': 'text/html' }); res.end(data); }); }

    const bodyBuf = (req.method === 'POST' || req.method === 'PUT' || req.method === 'DELETE') ? await readBody(req) : Buffer.alloc(0);
    const body = (() => { try { return bodyBuf.length ? JSON.parse(bodyBuf.toString()) : {}; } catch { return {}; } })();
    const user = currentUser(req);
    const needAdmin = () => { if (!user || user.role !== 'admin') { json(res, 403, { error: 'Admin only' }); return false; } return true; };

    // --- Auth ---
    if (p === '/api/setup-status') return json(res, 200, { needsSetup: !db.users.some((u) => u.role === 'admin') });
    if (p === '/api/setup' && req.method === 'POST') {
      if (db.users.some((u) => u.role === 'admin')) return json(res, 400, { error: 'Admin already exists' });
      const { email, password } = body;
      if (!email || !password || password.length < 8) return json(res, 400, { error: 'Email and a password of at least 8 characters are required' });
      const u = { id: crypto.randomUUID(), email: String(email).toLowerCase(), passwordHash: hashPassword(password), role: 'admin', createdAt: new Date().toISOString() };
      db.users.push(u); saveDb(db); setSession(res, u);
      return json(res, 200, { ok: true, user: publicUser(u) });
    }
    if (p === '/api/signup' && req.method === 'POST') {
      const email = String(body.email || '').toLowerCase().trim();
      if (!/.+@.+\..+/.test(email)) return json(res, 400, { error: 'Valid email required' });
      if (db.users.some((u) => u.email === email)) return json(res, 400, { error: 'Email already registered' });
      const password = generateLivePassword(); // LIVE format: 8 chars, numbers + letters + # @ * $
      const u = { id: crypto.randomUUID(), email, passwordHash: hashPassword(password), role: 'user', createdAt: new Date().toISOString() };
      db.users.push(u); saveDb(db);
      const sent = await sendPasswordEmail(email, password);
      if (!sent) { db.users = db.users.filter((x) => x.id !== u.id); saveDb(db); return json(res, 503, { error: 'Email service is not configured yet, so no account was created. Please try again later.' }); }
      // Never return the password in the API response.
      return json(res, 200, { ok: true, message: 'Password sent to your email. Log in with your email and that password.' });
    }
    if (p === '/api/login' && req.method === 'POST') {
      const email = String(body.email || '').toLowerCase().trim();
      const u = db.users.find((x) => x.email === email);
      if (!u || !verifyPassword(String(body.password || ''), u.passwordHash)) return json(res, 401, { error: 'Wrong email or password' });
      setSession(res, u); return json(res, 200, { ok: true, user: publicUser(u) });
    }
    if (p === '/api/forgot-password' && req.method === 'POST') {
      // Forgot password, per the standing auth rule: the website emails a NEW
      // random 8-digit password, replacing the old one. No reset code or link.
      // Only the newest website-sent password is then accepted, until the
      // account is deleted. The response is generic on purpose: it never
      // reveals whether an email exists.
      const email = String(body.email || '').toLowerCase().trim();
      const u = db.users.find((x) => x.email === email);
      if (u && u.role === 'user') {
        const password = generateLivePassword(); // LIVE format: 8 chars, numbers + letters + # @ * $
        const oldHash = u.passwordHash;
        u.passwordHash = hashPassword(password);
        // Invalidate existing sessions for this user: only the new password logs in.
        db.sessions = db.sessions.filter((x) => x.userId !== u.id);
        saveDb(db);
        const sent = await sendPasswordEmail(email, password);
        if (!sent) { u.passwordHash = oldHash; saveDb(db); }
      }
      // Never return the password, and never reveal whether the account exists.
      return json(res, 200, { ok: true, message: 'If an account exists, a new password was sent to your email.' });
    }
    if (p === '/api/delete-account' && req.method === 'POST') {
      // Delete-account: the live rule says a website-sent password stays
      // accepted until the user deletes their account. Deleting removes
      // the user row and all their sessions, then clears the cookie.
      // Admin accounts are not deleted here, so the site cannot lose its
      // only admin by accident; admin removal is a separate manual step.
      if (!user) return json(res, 401, { error: 'Login required' });
      if (user.role !== 'user') return json(res, 400, { error: 'Admin accounts cannot be deleted from this endpoint' });
      db.users = db.users.filter((x) => x.id !== user.id);
      db.sessions = db.sessions.filter((x) => x.userId !== user.id);
      saveDb(db);
      res.setHeader('Set-Cookie', 'session=; HttpOnly; Path=/; Max-Age=0');
      return json(res, 200, { ok: true, message: 'Account deleted.' });
    }
    if (p === '/api/logout' && req.method === 'POST') { clearSession(req, res); return json(res, 200, { ok: true }); }
    if (p === '/api/me') return json(res, 200, { user: publicUser(user) });

    // --- Public data ---
    if (p === '/api/services') return json(res, 200, { services: db.services.map(sanitiseService) });
    if (p === '/api/posts') return json(res, 200, { posts: db.posts });

    // Single listing detail: SERVER-GATED. /api/services is the public browse list only.
    // The full PDP detail requires a logged-in session; logged-out requests get 401, no detail.
    if (p.startsWith('/api/item/') && req.method === 'GET') {
      if (!user) return json(res, 401, { error: 'Login required to open this listing', requiresLogin: true });
      const found = findItem(decodeURIComponent(p.slice('/api/item/'.length)));
      if (!found) return json(res, 404, { error: 'Item not found' });
      const it = found.item;
      const detail = found.service.slug === 'prompt'
        ? { id: it.id, service: found.service.slug, serviceTitle: found.service.title, title: it.title, blurb: it.blurb, detail: found.service.full, image: it.image || '' }
        : { id: it.id, service: found.service.slug, serviceTitle: found.service.title, title: it.title, blurb: it.blurb, detail: found.service.full, price: it.price || '', stock: it.stock || '', image: it.image || '' };
      return json(res, 200, { item: detail });
    }

    // --- Admin ---
    if (p === '/api/admin/upload' && req.method === 'POST') {
      if (!needAdmin()) return;
      const ct = req.headers['content-type'] || '';
      const m = /boundary=(.+)/.exec(ct);
      if (!m) return json(res, 400, { error: 'Multipart upload required' });
      const parts = parseMultipart(bodyBuf, m[1].trim());
      const file = parts.find((x) => x.filename);
      if (!file) return json(res, 400, { error: 'No file uploaded' });
      const safeName = file.filename.replace(/[^a-zA-Z0-9._-]/g, '_');
      const name = Date.now() + '-' + safeName;
      fs.writeFileSync(path.join(UPLOAD_DIR, name), file.body);
      return json(res, 200, { ok: true, url: '/uploads/' + name });
    }
    if (p === '/api/admin/service' && req.method === 'POST') {
      if (!needAdmin()) return;
      const s = db.services.find((x) => x.slug === body.slug);
      if (!s) return json(res, 404, { error: 'Service not found' });
      if (body.title !== undefined) s.title = body.title;
      if (body.short !== undefined) s.short = body.short;
      if (body.full !== undefined) s.full = body.full;
      saveDb(db); return json(res, 200, { ok: true, service: sanitiseService(s) });
    }
    if (p === '/api/admin/item' && req.method === 'POST') {
      if (!needAdmin()) return;
      const s = db.services.find((x) => x.slug === body.slug);
      if (!s) return json(res, 404, { error: 'Service not found' });
      const it = { id: body.slug + '-' + Date.now(), title: body.title || 'New item', blurb: body.blurb || '', image: body.image || '' };
      if (s.slug !== 'prompt') { it.price = body.price || ''; it.stock = body.stock || ''; }
      s.items.push(it); saveDb(db); return json(res, 200, { ok: true, item: it });
    }
    const itemMatch = p.match(/^\/api\/admin\/item\/(.+)$/);
    if (itemMatch && (req.method === 'PUT' || req.method === 'DELETE')) {
      if (!needAdmin()) return;
      const found = findItem(decodeURIComponent(itemMatch[1]));
      if (!found) return json(res, 404, { error: 'Item not found' });
      if (req.method === 'DELETE') { found.service.items = found.service.items.filter((x) => x.id !== found.item.id); saveDb(db); return json(res, 200, { ok: true }); }
      if (body.title !== undefined) found.item.title = body.title;
      if (body.blurb !== undefined) found.item.blurb = body.blurb;
      if (body.image !== undefined) found.item.image = body.image;
      if (found.service.slug !== 'prompt') {
        if (body.price !== undefined) found.item.price = body.price;
        if (body.stock !== undefined) found.item.stock = body.stock;
      } else { delete found.item.price; delete found.item.stock; }
      saveDb(db); return json(res, 200, { ok: true, item: found.item });
    }
    if (p === '/api/admin/post' && req.method === 'POST') {
      if (!needAdmin()) return;
      const post = { id: 'post-' + Date.now(), title: body.title || '', body: body.body || '', image: body.image || '', createdAt: new Date().toISOString() };
      db.posts.push(post); saveDb(db); return json(res, 200, { ok: true, post });
    }
    const postMatch = p.match(/^\/api\/admin\/post\/(.+)$/);
    if (postMatch && (req.method === 'PUT' || req.method === 'DELETE')) {
      if (!needAdmin()) return;
      const post = db.posts.find((x) => x.id === decodeURIComponent(postMatch[1]));
      if (!post) return json(res, 404, { error: 'Post not found' });
      if (req.method === 'DELETE') { db.posts = db.posts.filter((x) => x.id !== post.id); saveDb(db); return json(res, 200, { ok: true }); }
      if (body.title !== undefined) post.title = body.title;
      if (body.body !== undefined) post.body = body.body;
      if (body.image !== undefined) post.image = body.image;
      saveDb(db); return json(res, 200, { ok: true, post });
    }

    return json(res, 404, { error: 'Not found' });
  } catch (e) {
    console.error(e);
    return json(res, 500, { error: 'Server error' });
  }
}

if (require.main === module) {
  const server = http.createServer(handleRequest);
  server.listen(PORT, () => {
    console.log(`Apnar digital LOCAL server running at http://localhost:${PORT}`);
    console.log('Open http://localhost:' + PORT + ' for the public page, /admin for the admin panel.');
    console.log('First run: open /admin-setup to create the admin account (hash only, no credentials in code).');
    if (!process.env.SMTP_HOST) console.log('DEMO MODE — no SMTP configured, no real email will be sent; outgoing passwords are saved to data/outbox.json (server side only).');
  });
}
module.exports = handleRequest;
